namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with some initial fake data
        _notifications.Add(new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-30)));
        _notifications.Add(new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-15)));
        _notifications.Add(new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-5)));
    }

    /// <summary>Returns all notifications created after the given ID (exclusive).</summary>
    public Task<List<Notification>> GetNotificationsAsync(int afterId = 0)
    {
        lock (_lock)
        {
            var result = _notifications.Where(n => n.Id > afterId).ToList();
            return Task.FromResult(result);
        }
    }

    /// <summary>Simulates new notifications arriving over time.</summary>
    public void SimulateIncoming()
    {
        var messages = new[]
        {
            "Server CPU usage is back to normal.",
            "A new user just signed up.",
            "Deployment to production completed.",
            "Backup finished successfully.",
            "Disk usage alert resolved.",
            "New comment on your pull request.",
            "Weekly report is ready to view."
        };

        lock (_lock)
        {
            var msg = messages[Random.Shared.Next(messages.Length)];
            _notifications.Add(new(NextId(), msg, DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorNotifications.Services
@inject NotificationService NotificationService
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@notifications.Count</span>
</h1>

@if (notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? RestoredNotifications { get; set; }

    private List<Notification> notifications = new();
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        if (RestoredNotifications is not null)
        {
            // Interactive render: state was restored from prerender — skip the fetch
            notifications = RestoredNotifications;
        }
        else
        {
            // Prerender: load initial data and let [PersistentState] serialize it
            notifications = await NotificationService.GetNotificationsAsync();
            RestoredNotifications = notifications;
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Only runs in the interactive render, never during prerender
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            // Simulate a new notification arriving on the server
            NotificationService.SimulateIncoming();

            var latestId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
            var newer = await NotificationService.GetNotificationsAsync(latestId);

            if (newer.Count > 0)
            {
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

